"use client";

import * as React from "react";
import { Progress as ProgressPrimitive } from "@base-ui/react/progress";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Airy docs Progress: a thin 0.375rem pale track with a flat green fill.
 * Leave `value` unset for an unknown amount, and a short fill pulses.
 */
const Progress = React.forwardRef<
  HTMLDivElement,
  Omit<WithClassName<ProgressPrimitive.Root.Props>, "value"> & {
    value?: ProgressPrimitive.Root.Props["value"];
  }
>(({ className, value, ...props }, ref) => (
  <ProgressPrimitive.Root
    ref={ref}
    data-slot="progress"
    value={value ?? null}
    className={cn("relative h-1.5 w-full overflow-hidden rounded-full bg-muted", className)}
    {...props}
  >
    <ProgressPrimitive.Track data-slot="progress-track" className="size-full">
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className="h-full rounded-full bg-primary transition-[width] duration-slow ease-out data-[indeterminate]:w-1/4 data-[indeterminate]:animate-pulse"
      />
    </ProgressPrimitive.Track>
  </ProgressPrimitive.Root>
));
Progress.displayName = "Progress";

export { Progress };
